scripts.track:
function find(req, field, value) {
  const d = db.query('SELECT * FROM deliveries WHERE id = ?', Number(req.params.id))[0];
  return d && value && d[field] === value ? d : null;
}
function shop() { return db.query('SELECT * FROM shop ORDER BY id LIMIT 1')[0]; }
// The customer's map. The token lets only this page read the delivery's live channel.
function handle(req) {
  const id = req.params.id || req.query.id;
  if (!id && !req.query.code) return {template: 'home'};
  req.params.id = id;
  const d = find(req, 'code', (req.query.code || '').trim().toUpperCase());
  if (!d) return {template: 'not_found', status: 404};
  if (!req.params.id || req.path === '/track') return {redirect: '/track/' + d.id + '?code=' + encodeURIComponent(d.code)};
  const texts = {preparing: 'Preparing', on_the_way: 'On the way', delivered: 'Delivered'};
  const channel = 'delivery-' + d.id;
  return {template: 'track', data: {id: d.id, shop: shop().name, phone: shop().phone, customer: d.customer_name, statusText: texts[d.status] || d.status,
    lat: d.lat || 0, lng: d.lng || 0, hasPos: d.lat !== null && d.lng !== null, updated: d.updated, channel: channel, token: realtime.token(channel)}};
}

