scripts.position:
function find(req, field, value) {
  const d = db.query('SELECT * FROM deliveries WHERE id = ?', Number(req.params.id))[0];
  return d && value && d[field] === value ? d : null;
}
function shop() { return db.query('SELECT * FROM shop ORDER BY id LIMIT 1')[0]; }
// The courier's phone sends its position; customers' maps move at once.
function handle(req) {
  const d = find(req, 'courier_key', req.form.key || '');
  if (!d) return {text: 'unknown delivery or key', status: 403};
  const lat = Number(req.form.lat), lng = Number(req.form.lng);
  if (!(lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180)) return {text: 'bad position', status: 400};
  db.exec("UPDATE deliveries SET lat = ?, lng = ?, updated = datetime('now'), status = CASE status WHEN 'preparing' THEN 'on_the_way' ELSE status END WHERE id = ?", lat, lng, d.id);
  realtime.publish({channel: 'delivery-' + d.id, data: {lat: lat, lng: lng, status: d.status === 'preparing' ? 'on_the_way' : d.status}});
  return {json: {ok: true}};
}

scripts.delivered:
function find(req, field, value) {
  const d = db.query('SELECT * FROM deliveries WHERE id = ?', Number(req.params.id))[0];
  return d && value && d[field] === value ? d : null;
}
function shop() { return db.query('SELECT * FROM shop ORDER BY id LIMIT 1')[0]; }
function handle(req) {
  const d = find(req, 'courier_key', req.form.key || '');
  if (!d) return {text: 'unknown delivery or key', status: 403};
  db.exec("UPDATE deliveries SET status = 'delivered' WHERE id = ?", d.id);
  realtime.publish({channel: 'delivery-' + d.id, data: {status: 'delivered'}});
  try { notify.owner({subject: 'Delivery #' + d.id + ' delivered to ' + d.customer_name, text: d.address || ''}); } catch (e) { console.warn('owner not told: ' + e); }
  return {json: {ok: true}};
}
